      SUBROUTINE DSHFTCC     CALCULATES THE PARTIAL DERIVATIVES OF THE FLOOR COORDINATESC     WITH RESPECT TO THE SHIFT IN THE BEAM REFERENCEC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'OIV.CIN'CC     LOCAL VARIABLESCC---------------------------------------------------------------------------C      IF (JV .EQ. 2 .OR. JV .EQ. 4) GO TO 10      IF (JV .EQ. 5 .OR. JV .EQ. 6) GO TO 100      IF (JV .EQ. 1) XIV(1) = - DPARM*UNITI(1)      IF (JV .EQ. 3) XIV(2) = - DPARM*UNITI(3)      GO TO 100CC     SHIFT IN ANGLEC   10 TNT1 = CO(2)      THETA1 = ATAN(TNT1)      CST1 = COS(THETA1)      SNT1 = SIN(THETA1)      TNP1 = CO(4)*CST1      PHI1 = ATAN(TNP1)      CSP1 = COS(PHI1)      SNP1 = SIN(PHI1)      PHI2 = ATAN(CO(4)-COD(4))      CSP2 = COS(PHI2)      SNP2 = SIN(PHI2)      THETA2 = ATAN((CO(2)-COD(2))*CSP2)      CST2 = COS(THETA2)      SNT2 = SIN(THETA2)CC     SHIFT IN HORIZONTAL ANGLEC      IF (JV .EQ. 4) GO TO 20      DCST1 = - SNT1*CST1**2*DPARM*UNITI(2)      DSNT1 = CST1**3*DPARM*UNITI(2)      OIV(1,1) = CST2*DCST1 + SNT2*DSNT1*CSP2*CSP1      OIV(1,2) = SNT2*SNP1      OIV(1,3) = CST2*DSNT1 - SNT2*DCST1*CSP1      OIV(2,1) = - SNT2*DCST1*SNP2 - DSNT1*CSP2*SNP1     1           + CST2*DSNT1*SNP2*CSP1      OIV(2,2) = CSP2*CSP1 + CST2*SNP2*SNP1      OIV(2,3) = - SNT2*DSNT1*SNP2 + DCST1*CSP2*SNP1     1         - CST2*DCST1*SNP2*CSP1      OIV(3,1) = SNT2*DCST1*CSP2 + SNT2*SNP2*SNP1     1           - CST2*DSNT1*CSP2*CSP1      OIV(3,2) = SNP2*CSP1 - CST2*CSP2*SNP1      OIV(3,3) = SNT2*DSNT1*CSP2 + DCST1*SNP2*SNP1     1         + CST2*DCST1*CSP2*CSP1      GO TO 100CC     SHIFT IN VERTICAL ANGLEC   20 DCSP1 = - SNP1*CSP1**2*DPARM*UNITI(4)      DSNP1 = CSP1**3*DPARM*UNITI(4)      OIV(1,1) = SNT2*SNT1*CSP2*DCSP1      OIV(1,2) = SNT2*DSNP1      OIV(1,3) = - SNT2*CST1*DCSP1      OIV(2,1) = SNT1*CSP2*DSNP1 + CST2*SNT1*SNP2*DCSP1      OIV(2,2) = CSP2*DCSP1 + CST2*SNP2*DSNP1      OIV(2,3) = CST1*CSP2*DSNP1 - CST2*CST1*SNP2*DCSP1      OIV(3,1) = SNT2*SNP2*DSNP1 - CST2*SNT1*CSP2*DCSP1      OIV(3,2) = SNP2*DCSP1 - CST2*CSP2*DSNP1      OIV(3,3) = CST1*SNP2*DSNP1 + CST2*CST1*CSP2*DCSP1C  100 RETURN      END